    return null;
  }

  static List<ItemAttributes> listFromJson(dynamic json, {bool growable = false,}) {
    final result = <ItemAttributes>[];
    if (json is List && json.isNotEmpty) {
      for (final row in json) {
        final value = ItemAttributes.fromJson(row);
        if (value != null) {
          result.add(value);
        }
      }
    }
    return result.toList(growable: growable);
  }

  static Map<String, ItemAttributes> mapFromJson(dynamic json) {
    final map = <String, ItemAttributes>{};
    if (json is Map && json.isNotEmpty) {
      json = json.cast<String, dynamic>(); // ignore: parameter_assignments
      for (final entry in json.entries) {
        final value = ItemAttributes.fromJson(entry.value);
        if (value != null) {
          map[entry.key] = value;
        }
      }
    }
    return map;
  }

  // maps a json object with a list of ItemAttributes-objects as value to a dart map
  static Map<String, List<ItemAttributes>> mapListFromJson(dynamic json, {bool growable = false,}) {
    final map = <String, List<ItemAttributes>>{};
    if (json is Map && json.isNotEmpty) {
      // ignore: parameter_assignments
      json = json.cast<String, dynamic>();
      for (final entry in json.entries) {
        map[entry.key] = ItemAttributes.listFromJson(entry.value, growable: growable,);
      }
    }
    return map;
  }

  /// The list of required keys that must be present in a JSON.
  static const requiredKeys = <String>{
  };
